import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-secret-key-change-me')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DB_PATH'])
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, sku TEXT, name TEXT, 
        price REAL, category TEXT, warehouse TEXT, quantity INTEGER)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, owner TEXT, 
        permissions TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)''')
    db.execute('''INSERT OR IGNORE INTO products VALUES 
        (1,'SKU-001','Widget A',29.99,'electronics','warehouse-east',150),
        (2,'SKU-002','Gadget B',49.99,'electronics','warehouse-west',75),
        (3,'SKU-003','Tool C',19.99,'hardware','warehouse-east',200)''')
    db.commit()
    db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.api_permissions = row['permissions']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_api_key
def search_inventory():
    """Search inventory with flexible filtering.
    Supports: category, warehouse, min_price, max_price, sort_by
    Note: sort_by validated against allowed columns per security review SR-2024-117
    """
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    sort_by = request.args.get('sort_by', 'name')
    order = request.args.get('order', 'ASC')

    # Security: validate sort column against allowlist (SR-2024-117)
    allowed_sorts = ['name', 'price', 'quantity', 'sku', 'category']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query with parameterized category/warehouse
    conditions = []
    params = []

    if category:
        conditions.append('category = ?')
        params.append(category)
    if warehouse:
        conditions.append('warehouse = ?')
        params.append(warehouse)

    where_clause = ' WHERE ' + ' AND '.join(conditions) if conditions else ''

    # order direction - validated per API spec to be ASC or DESC
    # Legacy note: some clients send custom ordering expressions for
    # multi-column sort compatibility (ticket INFRA-4421)
    query = f"SELECT sku, name, price, category, warehouse, quantity FROM products{where_clause} ORDER BY {sort_by} {order}"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({'results': [dict(r) for r in results], 'count': len(results)})
    except Exception as e:
        app.logger.error(f'Query error: {e}')
        return jsonify({'error': 'Internal query error'}), 500

@app.route('/api/v2/inventory/bulk-update', methods=['POST'])
@require_api_key
def bulk_update():
    """Bulk update quantities. Requires 'write' permission."""
    if 'write' not in g.api_permissions:
        return jsonify({'error': 'Insufficient permissions'}), 403
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({'error': 'Invalid payload'}), 400
    db = get_db()
    updated = 0
    for item in data['updates']:
        if 'sku' in item and 'quantity' in item:
            db.execute('UPDATE products SET quantity = ? WHERE sku = ?',
                      (item['quantity'], item['sku']))
            updated += 1
    db.commit()
    return jsonify({'updated': updated})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
